// is regenerated. Other voices get new rhythm, length, sound and per-step lanes.

function koreScopeRhythm(s) { return s === "RHYTHM" || s === "ALL"; }
function koreScopeSound(s) { return s === "SOUND" || s === "ALL"; }
function koreScopePLocks(s) { return s === "PLOCKS" || s === "ALL"; }

// ---------- style recipes (spec \u00a711 table) ----------
// lens: cycle lengths per voice [SUB, RUMBLE, TOM L, TOM H, HAT]
var KORE_STYLE = {
  FOUNDATION: { pickup: 0, sub: [1, 2], tomL: [1, 2], tomH: [0, 2], hat16: 0.08, hatOpen: [0, 1], fill: 0.1, poly: 0.1,
    lens: [[16, 32, 8], [16, 8, 32], [16, 8, 12, 32], [16, 12, 8, 32], [16, 8, 32]] },
  DRIVING: { pickup: 0.45, sub: [2, 4], tomL: [2, 3], tomH: [1, 3], hat16: 0.35, hatOpen: [1, 2], fill: 0.35, poly: 0.2,
    lens: [[16, 8, 12], [16, 8, 12], [16, 12, 14, 10], [16, 12, 14, 10], [16, 12, 8, 14]] },
  HYPNOTIC: { pickup: 0.1, sub: [2, 3], tomL: [2, 3], tomH: [2, 3], hat16: 0.15, hatOpen: [1, 1], fill: 0.05, poly: 0.45,
    lens: [[16, 12, 8], [16, 12, 6], [7, 11, 13, 5, 9], [5, 7, 11, 13, 10], [12, 15, 16, 14, 6]] },
  BROKEN: { pickup: 0.3, sub: [2, 4], tomL: [2, 4], tomH: [2, 4], hat16: 0.3, hatOpen: [1, 2], fill: 0.3, poly: 0.25,
    lens: [[16, 12, 10, 14], [16, 10, 14], [10, 12, 13, 14, 16], [10, 11, 13, 14, 16], [12, 13, 14, 15, 16]] }
};
var KORE_POLY_DIVS = [{ n: 3, m: 4 }, { n: 5, m: 4 }, { n: 7, m: 4 }];

// position weights by 16th position (mod 4: 0 beat, 1 e, 2 and, 3 a)
var KORE_PROFILE = [
  [1, 0.1, 0.2, 0.1],     // PUNCH (only pickups use this)
  [0.15, 0.6, 1, 0.7],    // SUB: responses between kicks
  [0.6, 0.3, 1, 0.3],     // RUMBLE gates
  [0.15, 0.6, 0.6, 1],    // TOM L: syncopated, off the kick
  [0.15, 0.9, 0.5, 1],    // TOM H
  [0.25, 0.6, 1, 0.6]     // HAT: offbeat
];
var KORE_MOTIFS_TOM = [[3, 11], [3, 7, 11], [5, 13], [6, 14], [7, 15], [3, 6, 11, 14], [10, 13], [2, 7, 13], [1, 9], [3, 10]];

function koreClearRhythm(track) {
  for (var i = 0; i < KORE_MAX_STEPS; i++) {
    var s = track.steps[i];
    s.on = false; s.velocity = 0.8; s.probability = 1; s.ratchet = 1; s.open = false;
  }
}
function koreSet(track, idx, vel, prob, ratchet, open) {
  if (idx < 0 || idx >= track.length) return;
  var s = track.steps[idx];
  s.on = true; s.velocity = koreRound(vel, 3); s.probability = prob === undefined ? 1 : koreRound(prob, 2);
  s.ratchet = ratchet || 1; s.open = !!open;
}
function koreHitAt(track, beatIdx16) { // is there a hit of a 1:1 track at 16th index?
  if (track.division.n !== 1 || track.division.m !== 1) return false;
  return track.steps[beatIdx16 % track.length].on;
}

// New length for a voice, different from its previous one (user request).
function korePickLength(rng, options, prev) {
  var opts = [];
  for (var i = 0; i < options.length; i++) if (options[i] !== prev) opts.push(options[i]);
  return opts.length ? rng.pick(opts) : (prev === 16 ? 12 : 16);
}

function koreGenPunch(tr, rng, cfg, g) {
  koreClearRhythm(tr);
  tr.length = 16; tr.division = { n: 1, m: 1 };
  for (var i = 0; i < 4; i++) koreSet(tr, KORE_FOUR_ON_FLOOR[i], rng.range(0.94, 1));
  if (rng.chance(cfg.pickup)) koreSet(tr, rng.pick([14, 15, 7]), rng.range(0.45, 0.6), rng.range(0.4, 0.7));
  if (g.style === "BROKEN" && g.unlockPunch && rng.chance(0.6)) {
    tr.steps[rng.pick([4, 8, 12])].on = false;          // selective omission, keep the downbeat
    koreSet(tr, rng.pick([3, 10, 11, 14]), rng.range(0.7, 0.9));
  }
}

function korePlaceWeighted(tr, rng, count, weightFn, velFn) {
  var w = [], i;
  for (i = 0; i < tr.length; i++) w.push(tr.steps[i].on ? 0 : weightFn(i));
  for (var c = 0; c < count; c++) {
    var j = rng.weighted(w);
    if (j < 0) break;
    w[j] = 0;
    var v = velFn(j);
    koreSet(tr, j, v[0], v[1]);
  }
}

function koreGenSub(tr, prev, rng, cfg, g, punch) {
  koreClearRhythm(tr);
  tr.length = korePickLength(rng, cfg.lens[0], prev.length); tr.division = { n: 1, m: 1 };
  var layer = g.kickInteraction === "LAYER" || (g.kickInteraction === "HYBRID" && rng.chance(0.25));
  var n = rng.int(cfg.sub[0], cfg.sub[1]) * Math.max(1, Math.round(tr.length / 16));
  korePlaceWeighted(tr, rng, n, function (i) {
    var w = KORE_PROFILE[1][i % 4] * (koreHitAt(punch, i) ? (g.kickInteraction === "ALTERNATE" ? 0 : 0.15) : 1);
    return w * rng.range(0.6, 1.4);
  }, function () { return [rng.range(0.6, 0.9), rng.chance(0.2) ? rng.range(0.6, 0.9) : 1]; });
  if (layer) koreSet(tr, 0, rng.range(0.45, 0.6)); // controlled layer under the downbeat
}

function koreGenRumble(tr, prev, rng, cfg, g) {
  koreClearRhythm(tr);
  tr.length = korePickLength(rng, cfg.lens[1], prev.length); tr.division = { n: 1, m: 1 };
  var mode = rng.pick(["offbeat", "kick", "sparse", "pulse"]);
  for (var i = 0; i < tr.length; i++) {
    var m = i % 4;
    if (mode === "offbeat" && m === 2) koreSet(tr, i, rng.range(0.75, 1));
    else if (mode === "kick" && m === 0) koreSet(tr, i, rng.range(0.7, 0.95));
    else if (mode === "sparse" && i % 8 === 2) koreSet(tr, i, rng.range(0.8, 1));
    else if (mode === "pulse" && i % 2 === 1 && rng.chance(0.6)) koreSet(tr, i, rng.range(0.5, 0.8), rng.chance(0.3) ? 0.7 : 1);
  }
  if (koreCountHits(tr) === 0) koreSet(tr, 2, 0.9);
}

function koreGenTom(tr, prev, rng, cfg, idx, others, punch) {
  koreClearRhythm(tr);
  tr.length = korePickLength(rng, cfg.lens[idx], prev.length);
  tr.division = rng.chance(cfg.poly) ? koreClone(rng.pick(KORE_POLY_DIVS)) : { n: 1, m: 1 };
  var range = idx === 2 ? cfg.tomL : cfg.tomH;
  var motif = rng.pick(KORE_MOTIFS_TOM), want = rng.int(Math.max(1, range[0]), Math.max(1, range[1]));
  var placed = 0;
  for (var i = 0; i < motif.length && placed < want; i++) {
    var p = motif[i] % tr.length;
    if (koreHitAt(punch, p) || others.some(function (o) { return koreHitAt(o, p); })) continue;
    koreSet(tr, p, rng.range(0.6, 0.9), rng.chance(0.2) ? rng.range(0.55, 0.85) : 1);
    placed++;
  }
  if (placed < want) korePlaceWeighted(tr, rng, want - placed, function (j) { return KORE_PROFILE[idx + 1][j % 4] * (koreHitAt(punch, j) ? 0.1 : 1); },
    function () { return [rng.range(0.55, 0.85), 1]; });
  if (rng.chance(cfg.fill) && tr.length >= 12) koreSet(tr, tr.length - 1, rng.range(0.6, 0.85), 1, rng.int(2, 3)); // short fill
  if (koreCountHits(tr) === 0) koreSet(tr, Math.min(3, tr.length - 1), 0.7);
}

function koreGenHat(tr, prev, rng, cfg) {
  koreClearRhythm(tr);
  tr.length = korePickLength(rng, cfg.lens[4], prev.length);
  tr.division = rng.chance(cfg.poly * 0.4) ? { n: 3, m: 4 } : { n: 1, m: 1 };
  var shift = (tr.length % 4 !== 0 && rng.chance(0.5)) ? 1 : 0; // cyclic displacement
  for (var i = 0; i < tr.length; i++) {
    if ((i + shift) % 4 === 2) koreSet(tr, i, rng.range(0.7, 0.95));
    else if (rng.chance(cfg.hat16) && (i % 2 === 1)) koreSet(tr, i, rng.range(0.35, 0.6), rng.chance(0.4) ? rng.range(0.5, 0.85) : 1, rng.chance(0.08) ? 2 : 1);
  }
  var opens = rng.int(cfg.hatOpen[0], cfg.hatOpen[1]), offs = [];
  for (var j = 0; j < tr.length; j++) if (tr.steps[j].on && tr.steps[j].velocity > 0.65) offs.push(j);
  for (var o = 0; o < opens && offs.length; o++) tr.steps[offs.splice(rng.int(0, offs.length - 1), 1)[0]].open = true;
  if (koreCountHits(tr) < 2) { koreSet(tr, 2 % tr.length, 0.8); koreSet(tr, 6 % tr.length, 0.8); }
}

// Validation (spec \u00a711.7): anchors, low-end overlap, density. Returns "" if fine.
function koreValidateGroove(tracks, g) {
  var punch = tracks[KORE_PUNCH];
  if (!(g.style === "BROKEN" && g.unlockPunch)) {
    for (var i = 0; i < 4; i++) if (!punch.steps[KORE_FOUR_ON_FLOOR[i]].on) return "punch anchor missing";
  }
  var heavy = 0;
  for (var s = 0; s < 16; s++) {
    var lf = 0;
    if (koreHitAt(punch, s)) lf++;
    if (koreHitAt(tracks[KORE_SUB], s) && tracks[KORE_SUB].steps[s % tracks[KORE_SUB].length].velocity > 0.6) lf++;
    if (koreHitAt(tracks[KORE_TOML], s)) lf++;
    if (lf >= 3) heavy++;
  }
  if (heavy > 1) return "too many stacked low-end hits";
  for (var t = 1; t < tracks.length; t++) {
    var tr = tracks[t], h = koreCountHits(tr);
    if (h === 0) return tr.name + " silent";
    if (h >= tr.length) return tr.name + " full";
  }
  return "";
}

function koreGenerateRhythm(next, prev, rng, g) {
  var cfg = KORE_STYLE[g.style] || KORE_STYLE.FOUNDATION;
  for (var attempt = 0; attempt < 16; attempt++) {
    var cand = koreClone(next);
    if (!cand[KORE_PUNCH].locks.rhythm) koreGenPunch(cand[KORE_PUNCH], rng, cfg, g);
    var punch = cand[KORE_PUNCH];
    if (!cand[KORE_SUB].locks.rhythm) koreGenSub(cand[KORE_SUB], prev[KORE_SUB], rng, cfg, g, punch);
    if (!cand[KORE_RUMBLE].locks.rhythm) koreGenRumble(cand[KORE_RUMBLE], prev[KORE_RUMBLE], rng, cfg, g);
    if (!cand[KORE_TOML].locks.rhythm) koreGenTom(cand[KORE_TOML], prev[KORE_TOML], rng, cfg, 2, [], punch);
    if (!cand[KORE_TOMH].locks.rhythm) koreGenTom(cand[KORE_TOMH], prev[KORE_TOMH], rng, cfg, 3, [cand[KORE_TOML]], punch);
    if (!cand[KORE_HAT].locks.rhythm) koreGenHat(cand[KORE_HAT], prev[KORE_HAT], rng, cfg);
    if (!koreValidateGroove(cand, g)) return cand;
  }
  // bounded: conservative FOUNDATION for the unlocked voices
  var safe = koreClone(next), def = koreDefaultState().tracks;
  for (var t = 0; t < safe.length; t++) {
    if (safe[t].locks.rhythm) continue;
    for (var i = 0; i < KORE_MAX_STEPS; i++) {
      var p = safe[t].steps[i].pLocks;
      safe[t].steps[i] = koreClone(def[t].steps[i]);
      safe[t].steps[i].pLocks = p;
    }
    safe[t].length = 16; safe[t].division = { n: 1, m: 1 };
  }
  return safe;
}

// ---------- sound ----------
var KORE_ARCHETYPES = [
  [ // PUNCH: tune punch decay drive click \u2014 club-safe ranges
    { name: "TIGHT", r: [[0.35, 0.6], [0.55, 0.85], [0.15, 0.4], [0.05, 0.3], [0.2, 0.5]] },
    { name: "BOOM", r: [[0.1, 0.35], [0.3, 0.6], [0.6, 0.95], [0, 0.2], [0, 0.2]] },
    { name: "HARD", r: [[0.3, 0.55], [0.6, 1], [0.3, 0.55], [0.4, 0.8], [0.3, 0.7]] },
    { name: "DEEP", r: [[0, 0.25], [0.2, 0.45], [0.5, 0.85], [0.1, 0.35], [0, 0.15]] },
    { name: "ROUND", r: [[0.25, 0.5], [0.35, 0.6], [0.35, 0.65], [0.05, 0.25], [0.05, 0.3]] }
  ],
  [ { name: "LOW", r: [[0, 0.35], [0.3, 0.7]] }, { name: "MID", r: [[0.35, 0.7], [0.2, 0.5]] }, { name: "LONG", r: [[0.1, 0.6], [0.6, 0.95]] } ],
  [ { name: "SOFT", r: [[0.2, 0.4], [0.3, 0.6], [0.5, 0.8]] }, { name: "DEEP", r: [[0.35, 0.65], [0.55, 0.9], [0.4, 0.75]] }, { name: "PULSE", r: [[0.3, 0.55], [0.1, 0.35], [0.6, 0.95]] } ],
  [ { name: "LOW TOM", r: [[0.05, 0.4], [0.3, 0.7], [0.1, 0.4]] }, { name: "CONGA", r: [[0.35, 0.7], [0.15, 0.4], [0.3, 0.6]] }, { name: "METAL TOM", r: [[0.3, 0.8], [0.2, 0.5], [0.6, 0.9]] } ],
  [ { name: "HIGH TOM", r: [[0.3, 0.7], [0.2, 0.55], [0.1, 0.4]] }, { name: "PERC", r: [[0.6, 1], [0.05, 0.3], [0.3, 0.7]] }, { name: "WOOD", r: [[0.45, 0.85], [0.05, 0.25], [0.55, 0.9]] } ],
  [ { name: "TIGHT", r: [[0.5, 0.9], [0.1, 0.35]] }, { name: "SOFT", r: [[0.2, 0.5], [0.3, 0.6]] }, { name: "BRIGHT", r: [[0.75, 1], [0.2, 0.5]] }, { name: "DARK", r: [[0, 0.3], [0.2, 0.5]] } ]
];

// Moves v by a non-zero amount (at a range end it moves inwards).
function koreNudge(v, size, rng, minStep) {
  var d = (rng.chance(0.5) ? 1 : -1) * rng.range(0.4, 1) * size;
  var mn = minStep === undefined ? 0.01 : minStep;
  if (Math.abs(d) < mn) d = d < 0 ? -mn : mn;
  var nv = koreClamp01(v + d);
  if (Math.abs(nv - v) < mn * 0.5) nv = koreClamp01(v - d);
  return koreRound(nv, 3);
}

// New sound for a voice: archetype different from the last one, every param random
// inside it, every base value guaranteed to change.
function koreGenerateSound(tr, rng) {
  var prev = koreClone(tr.params), list = KORE_ARCHETYPES[tr.id], keys = KORE_VOICE_PARAMS[tr.id];
  var idx = rng.int(0, list.length - 1);
  if (list[idx].name === tr.soundName && list.length > 1) idx = (idx + 1 + rng.int(0, list.length - 2)) % list.length;
  var a = list[idx];
  for (var i = 0; i < keys.length; i++) {
    var v = koreRound(rng.range(a.r[i][0], a.r[i][1]), 3);
    tr.params[keys[i]] = v === prev[keys[i]] ? koreNudge(v, 0.05, rng) : v;
  }
  tr.soundName = a.name;
}

// ---------- per-step lanes (P-Locks on every step, user D2) ----------
var KORE_LANE_DEPTH = [
  { tune: [0.01, 0.04], punch: [0.03, 0.12], decay: [0.04, 0.12], drive: [0.03, 0.12], click: [0.05, 0.2] }, // PUNCH: subtle
  { tune: [0.01, 0.04], decay: [0.05, 0.2] },                                                             // SUB: no octave jumps
  { amount: [0.1, 0.35], tail: [0.1, 0.3], duck: [0.05, 0.2] },
  { tune: [0.05, 0.25], decay: [0.1, 0.35], tone: [0.1, 0.4] },
  { tune: [0.05, 0.25], decay: [0.1, 0.35], tone: [0.1, 0.4] },
  { tone: [0.1, 0.35], decay: [0.1, 0.4] }
];
var KORE_LANE_STYLES = ["random", "ramp", "alternate", "wave", "accent", "walk"];

function koreLaneShape(style, L, rng) {
  var out = [], i;
  if (style === "random") for (i = 0; i < L; i++) out.push(rng.range(-1, 1));
  else if (style === "ramp") { var dir = rng.chance(0.5) ? 1 : -1; for (i = 0; i < L; i++) out.push(dir * (L > 1 ? -1 + 2 * i / (L - 1) : 0)); }
  else if (style === "alternate") { var per = rng.pick([2, 2, 3, 4]), sg = rng.chance(0.5) ? 1 : -1; for (i = 0; i < L; i++) out.push(sg * ((i % per) < per / 2 ? 1 : -1) * rng.range(0.7, 1)); }
  else if (style === "wave") { var period = rng.pick([3, 4, 5, 6, 8, 12, 16]), ph = rng.range(0, Math.PI * 2); for (i = 0; i < L; i++) out.push(Math.sin(ph + 2 * Math.PI * i / period)); }
  else if (style === "accent") for (i = 0; i < L; i++) out.push(rng.chance(0.28) ? (rng.chance(0.7) ? 1 : -1) * rng.range(0.6, 1) : rng.range(-0.15, 0.15));
  else { var x = rng.range(-0.5, 0.5); for (i = 0; i < L; i++) { x = koreClamp(x + rng.range(-0.45, 0.45), -1, 1); out.push(x); } }
  return out;
}

function koreDrawLane(tr, key, rng, scale) {
  var dr = KORE_LANE_DEPTH[tr.id][key], depth = rng.range(dr[0], dr[1]) * scale;
  var room = Math.min(depth, 0.5), base = koreClamp(tr.params[key], room, 1 - room);
  var shape = koreLaneShape(rng.pick(KORE_LANE_STYLES), tr.length, rng);
  for (var i = 0; i < KORE_MAX_STEPS; i++) {
    if (i < tr.length) tr.steps[i].pLocks[key] = koreRound(koreClamp01(base + depth * shape[i]), 3);
    else delete tr.steps[i].pLocks[key];
  }
}

function koreGenerateLanes(tr, rng, density, amount) {
  for (var i = 0; i < KORE_MAX_STEPS; i++) tr.steps[i].pLocks = {};
  if (density <= 0 || amount <= 0) return;
  var keys = KORE_VOICE_PARAMS[tr.id], scale = Math.min(2, amount / 0.5);
  for (var k = 0; k < keys.length; k++) if (rng.chance(density)) koreDrawLane(tr, keys[k], rng, scale);
}

// GENERATE: new tracks (input untouched). Locked parts untouched.
function koreGenerate(tracks, scope, rng, g) {
  var next = koreClone(tracks);
  if (koreScopeRhythm(scope)) next = koreGenerateRhythm(next, tracks, rng, g);
  for (var t = 0; t < next.length; t++) {
    var tr = next[t];
    if (tr.locks.sound) continue;
    if (koreScopeSound(scope)) koreGenerateSound(tr, rng);
    if (koreScopePLocks(scope)) koreGenerateLanes(tr, rng, g.lockDensity, g.lockAmount);
  }
  return koreNormalizeTracks(next);
}

// ---------- MUTATE (from the Keep anchor) ----------
function koreMoveHit(tr, from, to) {
  var a = tr.steps[from], b = tr.steps[to];
  b.on = true; b.velocity = a.velocity; b.probability = a.probability; b.ratchet = a.ratchet; b.open = a.open;
  a.on = false; a.ratchet = 1; a.probability = 1; a.open = false;
}

function koreMutateRhythm(tr, amount, rng, g) {
  var i, s;
  if (tr.id === KORE_PUNCH) { // foundation preserved: only velocities, scaled by amount\u00b2
    for (i = 0; i < tr.length; i++) {
      s = tr.steps[i];
      if (s.on) s.velocity = koreRound(koreClamp(s.velocity + rng.range(-1, 1) * 0.15 * amount * amount, 0.5, 1), 3);
    }
    return;
  }
  var L = tr.length, changes = Math.max(1, Math.floor(amount * L * 0.6 + rng.next()));
  for (var c = 0; c < changes; c++) {
    var on = [], off = [];
    for (i = 0; i < L; i++) (tr.steps[i].on ? on : off).push(i);
    var kind = rng.weighted([0.5, on.length < 2 ? 0.4 : 0.18, on.length <= 1 ? 0 : 0.18, 0.08, 0.06]);
    if (kind === 0 && on.length) {
      var from = rng.pick(on), cands = [];
      for (var d = -2; d <= 2; d++) { var to = (from + d + L) % L; if (d && !tr.steps[to].on) cands.push(to); }
      if (cands.length) koreMoveHit(tr, from, rng.pick(cands));
    } else if (kind === 1 && off.length) {
      var w = [];
      for (i = 0; i < off.length; i++) w.push(KORE_PROFILE[tr.id][off[i] % 4]);
      koreSet(tr, off[rng.weighted(w)], rng.range(0.45, 0.75));
    } else if (kind === 2 && on.length) {
      s = tr.steps[rng.pick(on)]; s.on = false; s.ratchet = 1; s.open = false;
    } else if (kind === 3 && on.length && tr.id !== KORE_SUB) {
      s = tr.steps[rng.pick(on)]; s.ratchet = s.ratchet > 1 ? 1 : rng.int(2, 3);
    } else if (on.length) {
      s = tr.steps[rng.pick(on)];
      if (tr.id === KORE_HAT && rng.chance(0.5)) s.open = !s.open;
      else s.probability = s.probability < 1 ? 1 : koreRound(rng.range(0.5, 0.9), 2);
    }
  }
  for (i = 0; i < L; i++) {
    s = tr.steps[i];
    if (s.on && rng.chance(amount)) s.velocity = koreRound(koreClamp(s.velocity + rng.range(-1, 1) * 0.15 * amount, 0.25, 1), 3);
  }
  if (amount >= 0.6 && rng.chance((amount - 0.5) * 0.5)) {
    var cfg = KORE_STYLE[g.style] || KORE_STYLE.FOUNDATION;
    tr.length = korePickLength(rng, cfg.lens[tr.id - 1], tr.length);
  }
  if (koreCountHits(tr) === 0) koreSet(tr, Math.min(2, tr.length - 1), 0.8);
}

function koreMutateSound(tr, amount, rng) {
  var keys = KORE_VOICE_PARAMS[tr.id], kick = tr.id === KORE_PUNCH;
  var size = kick ? 0.3 * amount * amount : 0.3 * amount; // small AMOUNT barely touches the kick
  for (var i = 0; i < keys.length; i++) tr.params[keys[i]] = koreNudge(tr.params[keys[i]], size, rng, kick ? 0 : 0.01);
}

function koreMutateLanes(tr, amount, rng, density, lockAmount) {
  var keys = KORE_VOICE_PARAMS[tr.id], kick = tr.id === KORE_PUNCH, scale = Math.min(2, lockAmount / 0.5);
  for (var k = 0; k < keys.length; k++) {
    var key = keys[k], has = true, i;
    for (i = 0; i < tr.length; i++) if (!tr.steps[i].pLocks.hasOwnProperty(key)) has = false;
    if (!has || (!kick && rng.chance(Math.max(0, amount - 0.25) * 0.6))) {
      if (density > 0) koreDrawLane(tr, key, rng, scale * (has ? 1 : Math.max(amount, 0.4)));
      continue;
    }
    for (i = 0; i < tr.length; i++) {
      var pl = tr.steps[i].pLocks;
      pl[key] = koreNudge(pl[key], (kick ? 0.3 * amount * amount : 0.3 * amount) * scale, rng, kick ? 0 : 0.01);
    }
  }
}

function koreCopyRhythm(dst, src) {
  dst.length = src.length; dst.division = koreClone(src.division);
  for (var i = 0; i < KORE_MAX_STEPS; i++) {
    var d = dst.steps[i], s = src.steps[i];
    d.on = s.on; d.velocity = s.velocity; d.probability = s.probability; d.ratchet = s.ratchet; d.open = s.open;
  }
}

function koreMutateFromAnchor(current, anchor, amount, scope, rng, g) {
  var next = koreClone(current);
  if (amount <= 0) return next; // exact no-op (A28)
  for (var t = 0; t < next.length; t++) {
    var tr = next[t], an = anchor[t], i;
    if (koreScopeRhythm(scope) && !tr.locks.rhythm) { koreCopyRhythm(tr, an); koreMutateRhythm(tr, amount, rng, g); }
    if (koreScopeSound(scope) && !tr.locks.sound) { tr.params = koreClone(an.params); koreMutateSound(tr, amount, rng); }
    if (koreScopePLocks(scope) && !tr.locks.sound) {
      for (i = 0; i < KORE_MAX_STEPS; i++) tr.steps[i].pLocks = koreClone(an.steps[i].pLocks);
      koreMutateLanes(tr, amount, rng, g.lockDensity, g.lockAmount);
    }
  }
  koreEnsureChanged(next, current, scope, rng, amount);
  var bad = koreValidateGroove(next, g);
  if (bad === "punch anchor missing") koreCopyRhythm(next[KORE_PUNCH], anchor[KORE_PUNCH]);
  return koreNormalizeTracks(next);
}

// Non-kick values must differ from what was playing before the press (user D3).
function koreEnsureChanged(next, current, scope, rng, amount) {
  for (var t = 1; t < next.length; t++) {
    var tr = next[t], cur = current[t], keys = KORE_VOICE_PARAMS[t], i, k, guard;
    if (tr.locks.sound) continue;
    if (koreScopeSound(scope)) for (i = 0; i < keys.length; i++) {
      k = keys[i];
      for (guard = 0; guard < 6 && tr.params[k] === cur.params[k]; guard++) tr.params[k] = koreNudge(tr.params[k], 0.02, rng);
    }
    if (koreScopePLocks(scope)) for (var s = 0; s < tr.length; s++) {
      var pl = tr.steps[s].pLocks, cp = cur.steps[s].pLocks;
      for (i = 0; i < keys.length; i++) {
        k = keys[i];
        if (!pl.hasOwnProperty(k)) continue;
        for (guard = 0; guard < 6 && cp.hasOwnProperty(k) && pl[k] === cp[k]; guard++) pl[k] = koreNudge(pl[k], 0.02, rng);
      }
    }
  }
}

// ---- js/src/40_engine.js ----
// K\u00d8RE core \u2014 engine: single source of truth + commands + history + playback.
// UI (compact and full) only sends commands; both read the same KoreEngine.

var KORE_UNDO_LIMIT = 16;
var KORE_BEATS_PER_BAR = 4; // v1 assumes 4/4 for "apply at next bar" (docs/DECISIONS.md D9)

function KoreEngine(opts) {
  opts = opts || {};
  this.state = koreDefaultState();
  this.anchorTracks = koreClone(this.state.tracks);  // Keep anchor
  this.undoStack = [];
  this.generationCounter = 0;
  this.playState = this.state;   // what the scheduler plays; differs only while a change is pending
  this.pending = false;
  this.transportPlaying = false;
  this.clock = new KoreClock(opts.clock);
  this.minSpacingMs = koreIsNum(opts.minSpacingMs) ? opts.minSpacingMs : 12;
  this.gesture = null;
  this.lastPos = 0;
  this.tempo = 120;
  this.listeners = [];
}

KoreEngine.prototype.onChange = function (fn) { this.listeners.push(fn); };
KoreEngine.prototype._changed = function (what) {
  for (var i = 0; i < this.listeners.length; i++) this.listeners[i](what);
};

// ---------- history ----------
KoreEngine.prototype._snapshot = function () {
  return {
    tracks: koreClone(this.state.tracks),
    anchorTracks: koreClone(this.anchorTracks),
    seed: this.state.global.seed,
    generationCounter: this.generationCounter
  };
};
KoreEngine.prototype._pushUndo = function (snap) {
  this.undoStack.push(snap || this._snapshot());
  while (this.undoStack.length > KORE_UNDO_LIMIT) this.undoStack.shift();
};
KoreEngine.prototype.canUndo = function () { return this.undoStack.length > 0; };

// Audio-affecting structural changes go through here: while the transport runs they
// are applied at the next bar (pending); when stopped, immediately.
KoreEngine.prototype._beginStructural = function () {
  if (this.transportPlaying && !this.pending) {
    this.playState = koreClone(this.state);
    this.pending = true;
  }
};
KoreEngine.prototype._applyPending = function () {
  this.playState = this.state;
  this.pending = false;
  this._changed("pending");
};

KoreEngine.prototype._nextSeed = function () {
  this.generationCounter++;
  this.state.global.seed = koreHashInts([this.state.global.seed, this.generationCounter, 0x4e30]) >>> 0;
  return this.state.global.seed;
};

// Scope follows the screen: SEQ \u2192 PATTERN (rhythm + P-Locks), SYNTH \u2192 SOUND.
// v0.3: GENERATE / MUTATE change everything (rhythm, sound, synth, per-step locks)
// on every screen; the L switch protects a voice.
KoreEngine.prototype.contextScope = function () { return "ALL"; };



// ---------- main commands ----------
KoreEngine.prototype.generate = function (scope) {
  scope = koreEnum(scope, KORE_SCOPES, "ALL");
  this._pushUndo();
  this._beginStructural();
  var rng = new KoreRng(this._nextSeed());
  this.state.tracks = koreGenerate(this.state.tracks, scope, rng, this.state.global);
  // D5: Generate makes the new result the anchor for following Mutates.
  this.anchorTracks = koreClone(this.state.tracks);
  if (!this.transportPlaying) this._applyPending();
  this._changed("generate");
};

KoreEngine.prototype.mutate = function (scope, amount) {
  scope = koreEnum(scope, KORE_SCOPES, "ALL");
  amount = koreIsNum(amount) ? koreClamp01(amount) : this.state.global.mutationAmount;
  if (amount <= 0) return false; // A07: nothing changes, no history entry
  this._pushUndo();
  this._beginStructural();
  var rng = new KoreRng(this._nextSeed()); // new unique seed every press
  this.state.tracks = koreMutateFromAnchor(this.state.tracks, this.anchorTracks, amount, scope, rng, this.state.global);
  if (!this.transportPlaying) this._applyPending();
  this._changed("mutate");
  return true;
};

KoreEngine.prototype.keep = function () {
  this._pushUndo();
  this.anchorTracks = koreClone(this.state.tracks);
  this._changed("keep");
};

KoreEngine.prototype.undo = function () {
  if (!this.undoStack.length) return false;
  var snap = this.undoStack.pop();
  this._beginStructural();
  this.state.tracks = snap.tracks;
  this.anchorTracks = snap.anchorTracks;
  this.state.global.seed = snap.seed;
  this.generationCounter = snap.generationCounter;
  if (!this.transportPlaying) this._applyPending();
  this._changed("undo");
  return true;
};

// ---------- edits ----------
// A gesture (mouse down \u2192 drag \u2192 mouse up) records exactly one undo entry.
KoreEngine.prototype.beginGesture = function () {
  if (!this.gesture) this.gesture = this._snapshot();
};
KoreEngine.prototype.endGesture = function () {
  if (!this.gesture) return;
  var before = this.gesture;
  this.gesture = null;
  if (JSON.stringify(before.tracks) !== JSON.stringify(this.state.tracks)) this._pushUndo(before);
};
// Discrete edit = its own one-entry gesture unless a gesture is already open.
KoreEngine.prototype._edit = function (fn, what) {
  var own = !this.gesture;
  if (own) this.beginGesture();
  fn.call(this);
  if (own) this.endGesture();
  this._changed(what || "edit");
};

KoreEngine.prototype._track = function (t) { return this.state.tracks[koreClamp(t | 0, 0, KORE_TRACK_NAMES.length - 1)]; };
KoreEngine.prototype._step = function (t, s) { return this._track(t).steps[koreClamp(s | 0, 0, KORE_MAX_STEPS - 1)]; };
KoreEngine.prototype._isParam = function (t, key) { return KORE_VOICE_PARAMS[this._track(t).id].indexOf(key) >= 0; };

KoreEngine.prototype.toggleStep = function (t, s) {
  this._edit(function () { var st = this._step(t, s); st.on = !st.on; }, "step");
};
KoreEngine.prototype.setStep = function (t, s, field, value) {
  this._edit(function () {
    var st = this._step(t, s);
    if (field === "on") st.on = !!value;
    else if (field === "velocity") st.velocity = koreClamp01(+value);
    else if (field === "probability") st.probability = koreClamp01(+value);
    else if (field === "ratchet") st.ratchet = koreClamp(Math.round(+value), 1, KORE_MAX_RATCHET);
    else if (field === "open") st.open = !!value;          // HAT articulation (choked)
  }, "step");
};
KoreEngine.prototype.setLength = function (t, n) {
  this._edit(function () { this._track(t).length = koreClamp(Math.round(+n), 1, KORE_MAX_STEPS); }, "track");
};
KoreEngine.prototype.setDivision = function (t, n, m) {
  this._edit(function () {
    this._track(t).division = { n: koreClamp(Math.round(+n), 1, KORE_MAX_DIV), m: koreClamp(Math.round(+m), 1, KORE_MAX_DIV) };
  }, "track");
};
// One "protect this voice" switch (L): rhythm + sound + P-Locks.
KoreEngine.prototype.setHold = function (t, on) {
  this._edit(function () { var tr = this._track(t); tr.locks.rhythm = !!on; tr.locks.sound = !!on; }, "lock");
};
KoreEngine.prototype.setLevel = function (t, db) { this._track(t).levelDb = koreClamp(+db, -60, 6); this._changed("mix"); };
KoreEngine.prototype.setMute = function (t, on) { this._track(t).mute = !!on; this._changed("mix"); };

// Turning a voice knob moves the whole per-step lane of that parameter (shape kept).
function koreShiftLane(track, key, delta) {
  if (!delta) return;
  for (var i = 0; i < KORE_MAX_STEPS; i++) {
    var pl = track.steps[i].pLocks;
    if (pl.hasOwnProperty(key)) pl[key] = koreRound(koreClamp01(pl[key] + delta), 4);
  }
}
KoreEngine.prototype.setBase = function (t, key, v) {
  if (!this._isParam(t, key)) return;
  this._edit(function () {
    var tr = this._track(t), nv = koreClamp01(+v);
    koreShiftLane(tr, key, nv - tr.params[key]);
    tr.params[key] = nv;
  }, "sound");
};
KoreEngine.prototype.setPLock = function (t, s, key, v) {
  if (!this._isParam(t, key)) return; // only ids of that voice (no leakage)
  this._edit(function () { this._step(t, s).pLocks[key] = koreClamp01(+v); }, "plock");
};
KoreEngine.prototype.clearLock = function (t, s, key) {
  this._edit(function () { delete this._step(t, s).pLocks[key]; }, "plock");
};
KoreEngine.prototype.clearStepLocks = function (t, s) {
  this._edit(function () { this._step(t, s).pLocks = {}; }, "plock");
};
// BASE or STEP P-Lock depending on the selected step \u2014 the call the UI uses.
KoreEngine.prototype.setParam = function (key, v) {
  var g = this.state.global;
  if (g.selectedStep >= 0) this.setPLock(g.selectedTrack, g.selectedStep, key, v);
  else this.setBase(g.selectedTrack, key, v);
};
KoreEngine.prototype.resetParam = function (key) {
  var g = this.state.global;
  if (!this._isParam(g.selectedTrack, key)) return;
  if (g.selectedStep >= 0) this.clearLock(g.selectedTrack, g.selectedStep, key);
  else this.setBase(g.selectedTrack, key, KORE_DEFAULT_PARAMS[g.selectedTrack][key]);
};

// ---------- global settings (UI state; no undo) ----------
KoreEngine.prototype.setGlobal = function (key, v) {
  var g = this.state.global;
  if (key === "mutationAmount" || key === "lockDensity" || key === "lockAmount") g[key] = koreClamp01(+v);
  else if (key === "style") g.style = koreEnum(String(v), KORE_STYLES, g.style);
  else if (key === "kickInteraction") g.kickInteraction = koreEnum(String(v), KORE_INTERACTIONS, g.kickInteraction);
  else if (key === "unlockPunch") g.unlockPunch = !!v;
  else if (key === "activeView") g.activeView = koreEnum(String(v), KORE_VIEWS, g.activeView);
  else if (key === "selectedTrack") { g.selectedTrack = koreClamp(v | 0, 0, 5); g.selectedStep = -1; }
  else if (key === "selectedStep") g.selectedStep = koreClamp(v | 0, -1, KORE_MAX_STEPS - 1);
  else if (key === "selectedPage") g.selectedPage = koreClamp(v | 0, 0, 1);
  else return;
  this._changed("global");
};

// ---------- playback ----------
// Called from the host clock bridge with the current host position (beats) and tempo.
// Returns events, each with `delayMs` (time from now until it must sound).
// Sets this.flushRequested when previously queued events must be dropped.
KoreEngine.prototype.tick = function (pos, tempo) {
  if (koreIsNum(tempo) && tempo > 0) this.tempo = tempo;
  this.flushRequested = false;
  var w = this.clock.advance(pos, this.tempo);
  var wasPlaying = this.transportPlaying;
  this.transportPlaying = this.clock.playing;
  if (wasPlaying && !this.transportPlaying && this.pending) this._applyPending();
  this.lastPos = pos;
  if (!w) return [];
  if (w.flush) {
    this.flushRequested = true;
    if (this.pending) this._applyPending(); // after a jump, apply right away
  }
  var msPerBeat = 60000 / this.tempo;
  var opt = { minSpacingBeats: (this.minSpacingMs / 60000) * this.tempo };
  var out = [];
  for (var i = 0; i < w.segments.length; i++) {
    var seg = w.segments[i];
    var parts = [];
    if (this.pending) {
      var bar = Math.ceil(seg.a / KORE_BEATS_PER_BAR - KORE_EPS) * KORE_BEATS_PER_BAR;
      if (bar < seg.b) {
        parts = koreEventsInRange(this.playState, seg.a, bar, opt);
        this._applyPending();
        parts = parts.concat(koreEventsInRange(this.state, bar, seg.b, opt));
      } else {
        parts = koreEventsInRange(this.playState, seg.a, seg.b, opt);
      }
    } else {
      parts = koreEventsInRange(this.state, seg.a, seg.b, opt);
    }
    for (var j = 0; j < parts.length; j++) {
      var ev = parts[j];
      ev.delayMs = Math.max(0, (seg.offset + (ev.beat - seg.a)) * msPerBeat);
      out.push(ev);
    }
  }
  return out;
};

KoreEngine.prototype.setLoop = function (on, start, length) { this.clock.setLoop(on, start, length); };

// ---------- persistence ----------
KoreEngine.prototype.serialize = function () {
  return koreSerialize(this.state, this.anchorTracks, this.generationCounter);
};
KoreEngine.prototype.restore = function (text) {
  var r = koreDeserialize(text);
  if (!r.ok) return r;
  this.state = r.state;
  this.anchorTracks = r.anchorTracks;
  this.generationCounter = r.generationCounter;
  this.playState = this.state;
  this.pending = false;
  this.undoStack = [];
  this._changed("restore");
  return r;
};

// Trigger message for the DSP: amplitude already includes velocity curve and level.
// Trigger for the DSP (8 values): track amp p0 p1 p2 p3 p4 open
// p0..p4 = the voice's params in KORE_VOICE_PARAMS order (unused slots 0).
function koreEventToTrigger(ev) {
  var amp = Math.pow(koreClamp01(ev.velocity), 1.5) * koreDbToAmp(ev.levelDb);
  var keys = KORE_VOICE_PARAMS[ev.trackId], out = [ev.trackId, koreRound(amp, 5)];
  for (var i = 0; i < 5; i++) out.push(i < keys.length ? koreRound(ev.params[keys[i]], 4) : 0);
  out.push(ev.open ? 1 : 0);
  return out;
}

// ---- js/max_adapter.js ----
// ===== K\u00d8RE \u2014 Max [js] adapter =====
// Appended after the core sources by js/build.js \u2192 max/kore_engine.js. ES5, low priority:
// timing comes from the lookahead + [pipe] in the patch, not from JS.
//
// Inlet 0:
//   tick <bars> <beats> <units> <resolution> <tempo>    host position from [transport]
//   loopon <0|1>  loopstart <beats>  looplength <beats> Live loop (live.observer)
//   generate | mutate | keep | undo
//   amount <0..1>  style <FOUNDATION|DRIVING|HYPNOTIC|BROKEN>  interaction <HYBRID|ALTERNATE|LAYER>
//   unlockpunch <0|1>
//   select <track>  selstep <step|-1>  page <0|1>  view <SEQUENCE|SOUND|LANES>
//   toggle <track> <step>  stepset <track> <step> <on|velocity|probability|ratchet|open> <value>
//   tracklength <track> <n>  division <track> <n> <m>  level <track> <dB>  mute <track> <0|1>
//   hold <track> <0|1>
//   param <key> <0..1>  paramreset <key>        (BASE or STEP P-Lock of the selected voice)
//   lane <track> <step> <key> <0..1>  clearlock <track> <step> <key>  clearsteplocks
//   gesture <1|0>
//   meter <peak>  kickmeter <peak>                from [peakamp~] (UI telemetry only)
//
// Outlet 0 \u2192 DSP:  trig <track> <amp> <p0> <p1> <p2> <p3> <p4> <open> <delayMs>
//                  flush
// Outlet 1 \u2192 UI:   bind <globalName> \u00b7 refresh \u00b7 playhead <s0..s5>
// Outlet 2 \u2192 status: sync <0|1> <tempo> \u00b7 pending <0|1> \u00b7 error <text>

autowatch = 1;
inlets = 1;
outlets = 3;

var engine = new KoreEngine({ clock: { lookaheadMs: 40, lateWindowMs: 12 } });

var registry = new Global("kore_registry");
registry.count = (registry.count || 0) + 1;
var uiName = "kore_ui_" + registry.count;
var ui = new Global(uiName);
ui.version = 0;
ui.meter = 0; ui.kick = 0;

var lastPlayhead = [-1, -1, -1, -1, -1, -1];
var lastSync = -1, lastPending = -1, dirtyPersist = false;

function publishUi() {
  ui.state = JSON.stringify({
    global: engine.state.global,
    tracks: engine.state.tracks,
    canUndo: engine.canUndo(),
    pending: engine.pending,
    playing: engine.transportPlaying,
    tempo: engine.tempo,
    defaults: { levelDb: KORE_DEFAULT_LEVEL_DB, params: KORE_DEFAULT_PARAMS }
  });
  ui.version++;
  outlet(1, "refresh");
}

engine.onChange(function (what) {
  publishUi();
  if (what !== "global" && what !== "pending") dirtyPersist = true;
  sendStatus();
});

function sendStatus() {
  var s = engine.transportPlaying ? 1 : 0;
  if (s !== lastSync) { lastSync = s; outlet(2, "sync", s, engine.tempo); publishUi(); }
  var p = engine.pending ? 1 : 0;
  if (p !== lastPending) { lastPending = p; outlet(2, "pending", p); publishUi(); }
}

function loadbang() { outlet(1, "bind", uiName); publishUi(); }
function bang() { outlet(1, "bind", uiName); publishUi(); }

// ---------- clock ----------
function tick(bars, beats, units, resolution, tempo) {
  var res = resolution > 0 ? resolution : 480;
  var pos = (bars - 1) * KORE_BEATS_PER_BAR + (beats - 1) + units / res;
  if (!(pos >= 0)) pos = 0;
  var evs = engine.tick(pos, tempo);
  if (engine.flushRequested) outlet(0, "flush");
  for (var i = 0; i < evs.length; i++) {
    var m = koreEventToTrigger(evs[i]);
    outlet(0, "trig", m[0], m[1], m[2], m[3], m[4], m[5], m[6], m[7], koreRound(evs[i].delayMs, 3));
  }
  var ph = [], changed = false;
  for (var t = 0; t < KORE_TRACK_NAMES.length; t++) {
    var s = engine.transportPlaying ? koreStepAt(engine.playState.tracks[t], pos) : -1;
    ph.push(s);
    if (s !== lastPlayhead[t]) changed = true;
  }
  if (changed) { lastPlayhead = ph; ui.playhead = ph; ui.pos = pos; outlet(1, "playhead", ph[0], ph[1], ph[2], ph[3], ph[4], ph[5]); }
  sendStatus();
}

var loopInfo = { on: 0, start: 0, length: 0 };
function loopon(v) { loopInfo.on = v; engine.setLoop(loopInfo.on, loopInfo.start, loopInfo.length); }
function loopstart(v) { loopInfo.start = v; engine.setLoop(loopInfo.on, loopInfo.start, loopInfo.length); }
function looplength(v) { loopInfo.length = v; engine.setLoop(loopInfo.on, loopInfo.start, loopInfo.length); }

// ---------- commands ----------
function generate() { engine.generate("ALL"); }
function mutate() { engine.mutate("ALL"); }
function keep() { engine.keep(); }
function undo() { engine.undo(); }
function amount(v) { engine.setGlobal("mutationAmount", v); }
function style(s) { engine.setGlobal("style", String(s)); }
function interaction(s) { engine.setGlobal("kickInteraction", String(s)); }
function unlockpunch(v) { engine.setGlobal("unlockPunch", v); }
function select(t) { engine.setGlobal("selectedTrack", t); }
function selstep(s) { engine.setGlobal("selectedStep", s); }
function page(p) { engine.setGlobal("selectedPage", p); }
function view(v) { engine.setGlobal("activeView", String(v)); }
function toggle(t, s) { engine.toggleStep(t, s); }
function stepset(t, s, field, v) { engine.setStep(t, s, String(field), v); }
function tracklength(t, n) { engine.setLength(t, n); }
function division(t, n, m) { engine.setDivision(t, n, m); }
function level(t, db) { engine.setLevel(t, db); }
function mute(t, v) { engine.setMute(t, v); }
function hold(t, v) { engine.setHold(t, v); }
function param(key, v) { engine.setParam(String(key), v); }
function paramreset(key) { engine.resetParam(String(key)); }
function lane(t, s, key, v) { engine.setPLock(t, s, String(key), v); }
function clearlock(t, s, key) { engine.clearLock(t, s, String(key)); }
function clearsteplocks() {
  var g = engine.state.global;
  if (g.selectedStep >= 0) engine.clearStepLocks(g.selectedTrack, g.selectedStep);
}
function gesture(on) { if (on) engine.beginGesture(); else engine.endGesture(); }
// telemetry from [peakamp~]: stored for the UI, never touches audio
function meter(v) { ui.meter = +v || 0; }
function kickmeter(v) { ui.kick = +v || 0; }
function dump() { post(engine.serialize() + "\n"); }

// ---------- persistence (pattr Blob parameter in the Live Set) ----------
function getvalueof() { dirtyPersist = false; return engine.serialize(); }
function setvalueof(v) {
  var r = engine.restore(arrayfromargs(arguments).join(" "));
  if (!r.ok) outlet(2, "error", "restore failed: " + r.error);
}
var persistTask = new Task(function () { if (dirtyPersist) { dirtyPersist = false; notifyclients(); } }, this);
persistTask.interval = 2000;
persistTask.repeat();
function notifydeleted() { persistTask.cancel(); }
